CREATE TABLE IF NOT EXISTS customer_password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_customer_reset_token (token_hash), KEY idx_customer_reset_lookup (customer_id, used_at, expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
